   108→}
   109→
   110→public fun ge_u64(a: Decimal, b: u64): bool {
   111→    a.value >= (b as u256 * WAD)
   112→}
   113→
   114→public fun gt(a: Decimal, b: Decimal): bool {
   115→    a.value > b.value
   116→}
   117→
   118→public fun gt_u64(a: &Decimal, b: u64): bool {
   119→    a.value > (b as u256 * WAD)
   120→}
   121→
   122→public fun le(a: Decimal, b: Decimal): bool {
