/// fixed point float representation. 18 decimal places are kept.
module math::float;

use math::math_error;

const U64_MAX_256: u256 = 18446744073709551615u256;
// VALUE_MAX_256 = U64_MAX_256 * WAD
const VALUE_MAX_256: u256 = 18446744073709551615000000000000000000u256;
const WAD: u256 = 1000000000000000000;

public struct Decimal has copy, drop, store {
    value: u256,
}

public fun zero(): Decimal { Decimal { value: 0 } }

public fun one(): Decimal { from(1) }

public fun from(v: u64): Decimal { Decimal { value: (v as u256) * WAD } }

public fun from_quotient(numerator: u64, denominator: u64): Decimal {
    Decimal {
        value: ensure_decimal_value_safe((numerator as u256) * WAD / (denominator as u256)),
    }
}

public fun is_zero(a: &Decimal): bool {
    a.value == 0
}

public fun add(a: Decimal, b: Decimal): Decimal {
    Decimal {
        value: ensure_decimal_value_safe(a.value + b.value),
    }
}

public fun add_u64(a: &Decimal, b: u64): Decimal {
    let value = b as u256 * WAD;
    Decimal {
        value: ensure_decimal_value_safe(a.value + value),
    }
}

public fun sub(a: Decimal, b: Decimal): Decimal {
    Decimal {
        value: a.value - b.value,
    }
}

public fun sub_u64(a: Decimal, b: u64): Decimal {
    let value = from(b);
    sub(a, value)
}

public fun saturating_sub(a: Decimal, b: Decimal): Decimal {
    if (a.value < b.value) {
        Decimal { value: 0 }
    } else {
        Decimal { value: a.value - b.value }
    }
}

public fun int_mul(a: Decimal, b: u64): u64 {
    safe_from_u256((a.value * (b as u256)) / WAD)
}

/// An integer divide this decimal: b / a = b / (a.value / WAD) = b * WAD / a.value
public fun int_div(b: u64, a: Decimal): u64 {
    safe_from_u256(WAD * (b as u256) / a.value)
}

public fun mul(a: Decimal, b: Decimal): Decimal {
    Decimal {
        value: ensure_decimal_value_safe((a.value * b.value) / WAD),
    }
}

public fun mul_u64(a: Decimal, b: u64): Decimal {
    let value = from(b);
    mul(a, value)
}

public fun div(a: Decimal, b: Decimal): Decimal {
    Decimal {
        value: ensure_decimal_value_safe((a.value * WAD) / b.value),
    }
}

public fun div_u64(a: Decimal, b: u64): Decimal {
    let value = from(b);
    div(a, value)
}

public fun floor(a: Decimal): u64 {
    safe_from_u256(a.value / WAD) as u64
}

public fun ceil(a: Decimal): u64 {
    safe_from_u256((a.value + WAD - 1) / WAD) as u64
}

public fun eq(a: Decimal, b: Decimal): bool {
    a.value == b.value
}

public fun ge(a: Decimal, b: Decimal): bool {
    a.value >= b.value
}

public fun ge_u64(a: Decimal, b: u64): bool {
    a.value >= (b as u256 * WAD)
}

public fun gt(a: Decimal, b: Decimal): bool {
    a.value > b.value
}

public fun gt_u64(a: &Decimal, b: u64): bool {
    a.value > (b as u256 * WAD)
}

public fun le(a: Decimal, b: Decimal): bool {
    a.value <= b.value
}

public fun lt(a: Decimal, b: Decimal): bool {
    a.value < b.value
}

public fun min(a: Decimal, b: Decimal): Decimal {
    if (a.lt(b)) a else b
}

public fun from_percent(v: u8): Decimal {
    Decimal {
        value: (v as u256) * WAD / 100,
    }
}

fun safe_from_u256(n: u256): u64 {
    assert!(n <= U64_MAX_256, math_error::overflow());
    n as u64
}

fun ensure_decimal_value_safe(n: u256): u256 {
    assert!(n <= VALUE_MAX_256, math_error::decimal_value_overflow());
    n
}

#[test_only]
public fun from_raw(v: u256): Decimal {
    Decimal {
        value: v
    }
}

#[test]
fun test_basic() {
    let a = from(1);
    let b = from(2);
    assert!(add(a, b) == from(3), 0);
    assert!(sub(b, a) == from(1), 0);
    assert!(mul(a, b) == from(2), 0);
    assert!(div(b, a) == from(2), 0);
    assert!(floor(from_percent(150)) == 1, 0);
    assert!(ceil(from_percent(150)) == 2, 0);
    assert!(lt(a, b), 0);
    assert!(gt(b, a), 0);
    assert!(le(a, b), 0);
    assert!(ge(b, a), 0);
}

#[test]
fun test_ceiling() {
    let a = from_quotient(101, 100);
    assert!(a.ceil() == 2);

    let a = from_raw(1);
    assert!(a.ceil() == 1);
}

#[test]
fun test_floor() {
    let a = from_quotient(101, 100);
    assert!(a.floor() == 1);

    let a = from_raw(1);
    assert!(a.floor() == 0);
}

